import {
	Component, ElementRef, forwardRef, Injector, Input, QueryList, ViewChild, ViewChildren
} from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { ButtonComponent } from 'espd-common/button';
import { Page } from 'espd-common/data';
import { ControlNameModule, espdAbstractInputComponentInjectionToken, EspdAbstractInputDirective, EspdFormControl, EspdFormGroup } from 'espd-common/forms/api';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { SearchComponent } from 'espd-common/forms/search';
import { MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { IconService } from 'espd-common/icon/utils';
import { ArrayUtils } from 'espd-common/utils';
import { WindowService } from 'espd-common/window';
import { PopoverDirective, PopoverModule } from 'ngx-bootstrap/popover';

@Component({
	selector: 'espd-icon-picker',
	templateUrl: './icon-picker.component.html',
	imports: [
		PopoverModule,
		ReactiveFormsModule,
		ControlNameModule,
		ButtonComponent,
		IconDirective,
		InputScaffoldComponent,
		MessageModule,
		SearchComponent
	],
	styleUrls: ['./icon-picker.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => IconPickerComponent) }]
})
export class IconPickerComponent extends EspdAbstractInputDirective<EspdFormControl<string>> {

	private static numColumns: number = 6; // keep in sync with scss file

	@Input()
	public pageSize: number = IconService.defaultPageSize;

	public pageNumber: number = 1;

	@ViewChild(SearchComponent)
	public searchComponent?: SearchComponent;

	@ViewChild('pop')
	public popover?: PopoverDirective;

	@ViewChildren('iconButton', { read: ElementRef })
	public iconButtons?: QueryList<ElementRef>;

	public page?: Page<string>;

	public form = new EspdFormGroup({ search: new EspdFormControl<string>('', { nonNullable: true }) });

	constructor(injector: Injector, private windowService: WindowService, private iconService: IconService) {
		super(injector);
		this.form.controls.search.valueChanges.subscribe(() => {
			this.pageNumber = 1;
			this.search();
		});
	}

	public search(): void {
		const term = this.form.controls.search.value!.toLocaleLowerCase();
		this.page = this.iconService.getPage(this.pageNumber, this.pageSize, term, true);
	}

	public isSelected(icon: string): boolean {
		return this.control.value === icon || (!this.control.value && icon === 'empty');
	}

	public popoverOpened(): void {
		this.form.controls.search.reset('');
		setTimeout(() => {
			this.pageNumber = this.iconService.getPageForIcon(this.control.value || 'empty');
			this.search();
			this.focusSearchInput();
		});
	}

	public previousPage(): void {
		this.pageNumber--;
		this.search();
	}

	public nextPage(): void {
		this.pageNumber++;
		this.search();
	}

	public move(direction: 'up' | 'down' | 'left' | 'right', event: Event): void {
		event.preventDefault();
		event.stopPropagation();
		let index = this.getFocusedIconIndex();
		if (index !== undefined) {
			index = ArrayUtils.navigate1DArrayIndexIn2DSpace(direction, index, this.page!.content.length, IconPickerComponent.numColumns);
			this.iconButtons?.get(index)?.nativeElement.focus();
		}
	}

	private getFocusedIconIndex(): number | undefined {
		const activeElement = this.windowService.nativeWindow.document.activeElement;
		const index = this.iconButtons?.toArray().map(ref => ref.nativeElement).findIndex(e => e === activeElement);
		return index !== undefined && index > -1 ? index : undefined;
	}

	private focusSearchInput(): void {
		this.searchComponent?.focusSearchInput();
	}

	public select(icon: string | null): void {
		if (icon === 'empty') {
			icon = null;
		}
		this.control.setValue(icon);
		this.control.markAsTouched();
		this.control.markAsDirty();
		this.popover?.hide();
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}